def generate_game_results(n):
    results = []
    for i in range(n - 1):
        for j in range(i + 1, n):
            if i % 2 == 0:
                results.append(0)  # Tie
            else:
                results.append(1 if i < j else -1)  # Team i wins if i < j, otherwise team j wins
    return results

def main():
    t = int(input())
    for _ in range(t):
        n = int(input())
        results = generate_game_results(n)
        print(' '.join(map(str, results)))

if __name__ == "__main__":
    main()
